// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != c.owner());
        vm.deal(address(c), 1 ether);
        uint256 balanceBefore = address(c).balance;

        vm.prank(caller);
        try c.withdrawAll() {} catch {}

        assertTrue(address(c).balance == balanceBefore);
    }
}
